using Wire = std::variant<CsvRecord, XmlRecord, KvRecord>;

struct ToCanonical {
    Canonical operator()(const CsvRecord &c)  const { return from_csv(c.raw); }
    Canonical operator()(const XmlRecord &x)  const { return from_xml(x.document); }
    Canonical operator()(const KvRecord &kv)  const { return from_kv(kv.pairs); }
};                                  // no generic auto-lambda: exhaustiveness is the point

Canonical normalize(const Wire &w) { return std::visit(ToCanonical{}, w); }

