};                                  // no generic auto-lambda: exhaustiveness is the point

Canonical normalize(const Wire &w) { return std::visit(ToCanonical{}, w); }

struct MessageTranslator {                       // one derived class per format
    virtual ~MessageTranslator() = default;
    virtual CanonicalMessage translate(const RawMessage &) const = 0;
};
class Normalizer {
    std::map<std::string, std::unique_ptr<MessageTranslator>> by_tag;
public:
    CanonicalMessage normalize(const RawMessage &raw) const {
        auto it = by_tag.find(detect_tag(raw));          // router
        if (it == by_tag.end()) throw UnknownFormat{detect_tag(raw)};
        return it->second->translate(raw);               // the matching translator
    }
};
